class TestDirtyDisplay:
    """Test the display name generation logic used by _refresh_file_list."""

    @staticmethod
    def _make_display(names: list[str], dirty: set[str]) -> list[str]:
        """Replicate the display name logic from _refresh_file_list."""
        return [f"{_DIRTY_PREFIX}{n}" if n in dirty else n for n in names]

    def test_no_dirty_files(self) -> None:
        names = ["a.html", "b.html"]
        assert self._make_display(names, set()) == ["a.html", "b.html"]

    def test_one_dirty_file(self) -> None:
        names = ["a.html", "b.html", "c.html"]
        dirty = {"b.html"}
        result = self._make_display(names, dirty)
        assert result == ["a.html", "* b.html", "c.html"]

    def test_all_dirty(self) -> None:
        names = ["a.html", "b.html"]
        dirty = {"a.html", "b.html"}
        result = self._make_display(names, dirty)
        assert result == ["* a.html", "* b.html"]

    def test_dirty_file_not_in_names(self) -> None:
        names = ["a.html"]
        dirty = {"gone.html"}
        result = self._make_display(names, dirty)
        assert result == ["a.html"]

    def test_round_trip_strip(self) -> None:
        """Display name with prefix round-trips through _strip_dirty."""
        display = f"{_DIRTY_PREFIX}plan.html"
        assert _strip_dirty(display) == "plan.html"


