class TestDirtyFileTracking:
    """Test the dirty file set operations used by PagesTab."""

    def test_discard_clears_file(self) -> None:
        dirty: set[str] = {"a.html", "b.html"}
        dirty.discard("a.html")
        assert dirty == {"b.html"}

    def test_discard_nonexistent_is_safe(self) -> None:
        dirty: set[str] = {"a.html"}
        dirty.discard("z.html")
        assert dirty == {"a.html"}

    def test_clear_empties_set(self) -> None:
        dirty: set[str] = {"a.html", "b.html", "c.html"}
        dirty.clear()
        assert dirty == set()

    def test_add_on_mtime_change(self) -> None:
        """Simulate _poll_files adding dirty files on mtime change."""
        dirty: set[str] = set()
        old_mtimes = {"a.html": 100.0, "b.html": 200.0}
        new_mtimes = {"a.html": 100.0, "b.html": 300.0}  # b changed

        for name, mtime in new_mtimes.items():
            old = old_mtimes.get(name, 0.0)
            if old != 0.0 and mtime != old:
                dirty.add(name)

        assert dirty == {"b.html"}

    def test_multiple_changes_accumulate(self) -> None:
        """Dirty files accumulate across polls until cleared."""
        dirty: set[str] = set()

        # First poll: b changes
        dirty.add("b.html")
        # Second poll: a changes
        dirty.add("a.html")

        assert dirty == {"a.html", "b.html"}

        # User selects a.html
        dirty.discard("a.html")
        assert dirty == {"b.html"}

        # User selects b.html
        dirty.discard("b.html")
        assert dirty == set()
